/**
 * Emits the cross-runtime command-tree golden fixture (native cutover
 * NATIVE-M1 CLI parity part 1 / go PARITY M8 help-golden gate):
 *
 *   go/testdata/parity/cli-tree.json
 *
 * The TypeScript CLI is behavioral authority, so the fixture is generated by
 * introspecting the commander program built from src/cli/commands.ts WITHOUT
 * invoking any action handler — the AnyPickApp is a registration-time stub and
 * every .action() callback is never called. The Go side asserts against this
 * fixture in go/cmd/anypick/help_parity_test.go.
 *
 * Usage: npx tsx scripts/parity-cli-tree.ts
 */

import { mkdir, writeFile } from 'node:fs/promises';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');

// Isolate from developer-machine state before importing anything that reads it.
process.env.HOME = repoRoot; // buildProgram only touches app members lazily
delete process.env.ANYPICK_HOME;

interface TreeEntry {
  path: string;
  description: string;
  flags: string[];
  subcommands: string[];
  hidden: boolean;
}

// Commands that exist on exactly one side of the cutover for documented
// reasons. The Go test treats these as expected drift instead of failures.
const OMITTED: Array<{ path: string; reason: string }> = [
  // plan §Scope: the interactive TUI ships with the TypeScript build only.
  { path: 'tui', reason: 'plan §Scope' },
  // JS plugin host is GO-PARITY-M7; the command group has no Go counterpart.
  { path: 'plugin', reason: 'GO-PARITY-M7' },
  // Hidden foreground supervisor variant; Go routes `tray …` to its helpers.
  { path: 'tray run', reason: 'hidden foreground supervisor (TS-only variant)' },
  // Go-side supervisor helpers with no TS top-level equivalent (PARITY_PLAN M8:
  // "tray, start, status, stop, and required hidden supervisor commands").
  { path: 'app', reason: 'Go supervisor entry (TS: tray run)' },
  { path: 'serve', reason: 'Go core status server helper' },
  { path: 'start', reason: 'Go top-level alias of TS tray start' },
  { path: 'status', reason: 'Go top-level alias of TS tray status' },
  { path: 'stop', reason: 'Go top-level alias of TS tray stop' },
  { path: 'stop-proxy', reason: 'Go legacy alias of TS proxy stop' },
  { path: '_serve-hub', reason: 'hidden detached helper (ADR 0003)' },
  { path: '_serve-pool', reason: 'hidden detached helper (ADR 0003)' },
  { path: '_serve-proxy', reason: 'hidden detached helper (ADR 0003)' },
  { path: '_supervise', reason: 'hidden detached helper (ADR 0003)' },
];

/** Registration-time stub: buildProgram destructures these but never calls them. */
function stubApp(): Record<string, unknown> {
  const empty = () => ({});
  return {
    root: '/anypick-parity-stub',
    accounts: empty(),
    profiles: empty(),
    catalog: { list: () => [] },
    clients: empty(),
    doctor: empty(),
    bindings: empty(),
    bindingService: empty(),
    presets: empty(),
    plugins: empty(),
    proxy: empty(),
    config: { read: async () => ({}) },
  };
}

function flagsOf(cmd: { options: Array<{ long: string; short?: string }> }): string[] {
  const out: string[] = [];
  for (const opt of cmd.options ?? []) {
    if (opt.long) out.push(opt.long);
    if (opt.short) out.push(opt.short);
  }
  return out;
}

const { buildProgram } = await import('../src/cli/commands');
const program = buildProgram(stubApp() as never);

const commands: TreeEntry[] = [];
function walk(cmd: { commands: Array<Record<string, any>> }, prefix: string[]): void {
  for (const child of cmd.commands) {
    const path = [...prefix, child.name()].join(' ');
    commands.push({
      path,
      description: child.description() ?? '',
      flags: flagsOf(child),
      subcommands: (child.commands ?? []).map((c: { name(): string }) => c.name()),
      hidden: Boolean(child.hidden),
    });
    walk(child, [...prefix, child.name()]);
  }
}
commands.push({
  path: '',
  description: program.description() ?? '',
  flags: flagsOf(program),
  subcommands: program.commands.map((c) => c.name()),
  hidden: false,
});
walk(program, []);

const destination = join(repoRoot, 'go', 'testdata', 'parity', 'cli-tree.json');
await mkdir(dirname(destination), { recursive: true });
await writeFile(destination, JSON.stringify({ commands, omitted: OMITTED }, null, 2) + '\n');
console.log(`cli-tree fixture: ${destination} (${commands.length} commands)`);
